def _insider_share_change_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    if endpoint_name == "stock_hold_management_person_em":
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the AKShare management-person endpoint supports A-share listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(
            set(request.parameters) - _INSIDER_MANAGEMENT_PERSON_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare management-person parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _INSIDER_MANAGEMENT_PERSON_VIEW:
            raise ProviderRequestError(
                "the AKShare management-person endpoint requires "
                f"view={_INSIDER_MANAGEMENT_PERSON_VIEW!r}",
                request=request,
                retryable=False,
            )
        name = request.parameters.get("name")
        if not isinstance(name, str) or not name.strip():
            raise ProviderRequestError(
                "the AKShare management-person endpoint requires a non-empty string "
                "name parameter",
                request=request,
                retryable=False,
            )
        return {"symbol": listing.code, "name": name}

    if endpoint_name == "stock_ggcg_em":
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the AKShare executive share-change endpoint supports A-share "
                "listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(
            set(request.parameters) - _EXECUTIVE_SHARE_CHANGES_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare executive share-change parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _EXECUTIVE_SHARE_CHANGES_VIEW:
            raise ProviderRequestError(
                "the AKShare executive share-change endpoint requires "
                f"view={_EXECUTIVE_SHARE_CHANGES_VIEW!r}",
                request=request,
                retryable=False,
            )
        direction = request.parameters.get("direction")
        if not isinstance(direction, str):
            raise ProviderRequestError(
                "the AKShare executive share-change endpoint requires a string "
                "direction parameter",
                request=request,
                retryable=False,
            )
        if direction not in _EXECUTIVE_SHARE_CHANGES_DIRECTIONS:
            choices = ", ".join(_EXECUTIVE_SHARE_CHANGES_DIRECTION_CHOICES)
            raise ProviderRequestError(
                "the AKShare executive share-change direction must be one of: "
                + choices,
                request=request,
                retryable=False,
            )
        return {"symbol": direction}

    if endpoint_name == "stock_hold_management_detail_cninfo":
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the AKShare CNINFO management-holding endpoint supports A-share "
                "listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(
            set(request.parameters)
            - _INSIDER_CNINFO_MANAGEMENT_DETAIL_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare CNINFO management-holdings parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _INSIDER_CNINFO_MANAGEMENT_DETAIL_VIEW:
            raise ProviderRequestError(
                "the AKShare CNINFO management-holding endpoint requires "
                f"view={_INSIDER_CNINFO_MANAGEMENT_DETAIL_VIEW!r}",
                request=request,
                retryable=False,
            )
        direction = request.parameters.get("direction")
        if not isinstance(direction, str):
            raise ProviderRequestError(
                "the AKShare CNINFO management-holding endpoint requires a string "
                "direction parameter",
                request=request,
                retryable=False,
            )
        if direction not in _INSIDER_CNINFO_MANAGEMENT_DETAIL_DIRECTIONS:
            choices = ", ".join(sorted(_INSIDER_CNINFO_MANAGEMENT_DETAIL_DIRECTIONS))
            raise ProviderRequestError(
                "the AKShare CNINFO management-holding direction must be one of: "
                + choices,
                request=request,
                retryable=False,
            )
        return {"symbol": direction}

    if endpoint_name == "stock_hold_management_detail_em":
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the AKShare management-holding endpoint supports A-share listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(set(request.parameters) - _INSIDER_MANAGEMENT_DETAIL_PARAMETER_NAMES)
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare management-holdings parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _INSIDER_MANAGEMENT_DETAIL_VIEW:
            raise ProviderRequestError(
                "the AKShare management-holding endpoint requires "
                f"view={_INSIDER_MANAGEMENT_DETAIL_VIEW!r}",
                request=request,
                retryable=False,
            )
        return {}

    exchange_by_endpoint = {
        "stock_share_hold_change_sse": "SH",
        "stock_share_hold_change_szse": "SZ",
        "stock_share_hold_change_bse": "BJ",
    }
    expected_exchange = exchange_by_endpoint.get(endpoint_name)
    if expected_exchange is None:
        raise ProviderRequestError(
            f"unsupported AKShare insider-share-change endpoint {endpoint_name!r}",
            request=request,
            retryable=False,
        )
    if listing.canonical_id[:2] != expected_exchange:
        raise ProviderRequestError(
            f"the {endpoint_name} endpoint supports {expected_exchange} A-share listings only",
            request=request,
            retryable=False,
        )
    unknown = sorted(set(request.parameters) - _INSIDER_SHARE_CHANGE_PARAMETER_NAMES)
    if unknown:
        raise ProviderRequestError(
            "unsupported AKShare insider-share-change parameter(s): " + ", ".join(unknown),
            request=request,
            retryable=False,
        )
    return {"symbol": listing.code}


