def _corporate_action_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    if endpoint_name == "stock_ipo_summary_cninfo":
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the AKShare IPO-summary endpoint supports A-share listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(set(request.parameters) - _IPO_SUMMARY_PARAMETER_NAMES)
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare IPO-summary parameter(s): " + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _IPO_SUMMARY_VIEW:
            raise ProviderRequestError(
                "AKShare IPO-summary endpoint requires "
                f"view={_IPO_SUMMARY_VIEW!r}",
                request=request,
                retryable=False,
            )
        return {"symbol": listing.code}
    if endpoint_name == "stock_dxsyl_em":
        if listing.market is not ListingMarket.A:
            raise ProviderRequestError(
                "the AKShare IPO-yield endpoint supports A-share listings only",
                request=request,
                retryable=False,
            )
        unknown = sorted(set(request.parameters) - _IPO_YIELD_PARAMETER_NAMES)
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare IPO-yield parameter(s): " + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _IPO_YIELD_VIEW:
            raise ProviderRequestError(
                "AKShare IPO-yield endpoint requires "
                f"view={_IPO_YIELD_VIEW!r}",
                request=request,
                retryable=False,
            )
        return {}
    if endpoint_name == "stock_repurchase_em":
        _reject_unexpected_parameters(request)
        return {}
    if endpoint_name != "stock_allotment_cninfo":
        raise ProviderRequestError(
            f"unsupported AKShare corporate-action endpoint {endpoint_name!r}",
            request=request,
            retryable=False,
        )
    if listing.market is not ListingMarket.A:
        raise ProviderRequestError(
            "the AKShare rights-issue endpoint supports A-share listings only",
            request=request,
            retryable=False,
        )
    unknown = sorted(set(request.parameters) - _CORPORATE_ACTION_PARAMETER_NAMES)
    if unknown:
        raise ProviderRequestError(
            "unsupported AKShare corporate-action parameter(s): " + ", ".join(unknown),
            request=request,
            retryable=False,
        )
    start_date, start_value = _allotment_date_parameter(
        request.parameters.get("start_date", _ALLOTMENT_DEFAULT_START_DATE),
        name="start_date",
        request=request,
    )
    end_date, end_value = _allotment_date_parameter(
        request.parameters.get("end_date", _ALLOTMENT_DEFAULT_END_DATE),
        name="end_date",
        request=request,
    )
    if start_value is not None and end_value is not None and start_value > end_value:
        raise ProviderRequestError(
            "corporate-action start_date must not be after end_date",
            request=request,
            retryable=False,
        )
    return {"symbol": listing.code, "start_date": start_date, "end_date": end_date}


