def _market_quote_index_sina_spot_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
) -> str | None:
    """Return strict-schema errors for the complete Sina index universe."""

    seen_codes: set[str] = set()
    previous_code: str | None = None
    for index, row in enumerate(rows):
        missing = [
            field
            for field in _MARKET_QUOTE_INDEX_SINA_SPOT_FIELDS
            if field not in row
        ]
        unexpected = [
            field
            for field in row
            if field not in _MARKET_QUOTE_INDEX_SINA_SPOT_FIELD_SET
        ]
        if missing:
            return (
                f"Sina index spot row {index} is missing field(s): "
                + ", ".join(missing)
            )
        if unexpected:
            return (
                f"Sina index spot row {index} contains unsupported field(s): "
                + ", ".join(unexpected)
            )
        if tuple(row) != _MARKET_QUOTE_INDEX_SINA_SPOT_FIELDS:
            return "Sina index spot rows must preserve the documented field order"

        code = row["代码"]
        if (
            not isinstance(code, str)
            or re.fullmatch(r"(?:sh|sz)\d{6}", code) is None
        ):
            return f"Sina index spot row {index} has an invalid 代码"
        if code in seen_codes:
            return f"Sina index spot response has duplicate 代码 {code!r}"
        if previous_code is not None and code < previous_code:
            return "Sina index spot 代码 values must be non-decreasing"
        seen_codes.add(code)
        previous_code = code

        name = row["名称"]
        if not isinstance(name, str) or not name.strip():
            return (
                f"Sina index spot row {index} field '名称' must be a "
                "non-empty string"
            )

        for field in _MARKET_QUOTE_INDEX_SINA_SPOT_NUMERIC_FIELDS:
            value = row[field]
            if value is None:
                continue
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    f"Sina index spot row {index} field {field!r} must be "
                    "numeric or null"
                )
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    f"Sina index spot row {index} field {field!r} must be "
                    "numeric or null"
                )
            if not math.isfinite(numeric):
                return (
                    f"Sina index spot row {index} field {field!r} must be "
                    "finite or null"
                )
    return None


