def _market_quote_hk_index_spot_em_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
) -> str | None:
    """Return strict-schema errors for the complete Eastmoney H-index universe."""

    seen_codes: set[str] = set()
    previous_rank: int | None = None
    for index, row in enumerate(rows):
        missing = [
            field
            for field in _MARKET_QUOTE_HK_INDEX_SPOT_EM_FIELDS
            if field not in row
        ]
        unexpected = [
            field
            for field in row
            if field not in _MARKET_QUOTE_HK_INDEX_SPOT_EM_FIELD_SET
        ]
        if missing:
            return (
                f"Eastmoney Hong Kong-index spot row {index} is missing field(s): "
                + ", ".join(missing)
            )
        if unexpected:
            return (
                f"Eastmoney Hong Kong-index spot row {index} contains unsupported "
                "field(s): "
                + ", ".join(unexpected)
            )
        if tuple(row) != _MARKET_QUOTE_HK_INDEX_SPOT_EM_FIELDS:
            return (
                "Eastmoney Hong Kong-index spot rows must preserve the documented "
                "field order"
            )

        for field in _MARKET_QUOTE_HK_INDEX_SPOT_EM_INTEGER_FIELDS:
            value = row[field]
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    f"Eastmoney Hong Kong-index spot row {index} field {field!r} "
                    "must be a positive integer"
                )
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    f"Eastmoney Hong Kong-index spot row {index} field {field!r} "
                    "must be a positive integer"
                )
            if (
                not math.isfinite(numeric)
                or not numeric.is_integer()
                or numeric < 1
            ):
                return (
                    f"Eastmoney Hong Kong-index spot row {index} field {field!r} "
                    "must be a positive integer"
                )

        normalized_rank = int(float(row["序号"]))
        if previous_rank is not None and normalized_rank <= previous_rank:
            return (
                "Eastmoney Hong Kong-index spot 序号 values must be strictly "
                "ascending"
            )
        previous_rank = normalized_rank

        code = row["代码"]
        if not isinstance(code, str) or re.fullmatch(r"[A-Z][A-Z0-9]+", code) is None:
            return f"Eastmoney Hong Kong-index spot row {index} has an invalid 代码"
        if code in seen_codes:
            return (
                "Eastmoney Hong Kong-index spot response has duplicate "
                f"代码 {code!r}"
            )
        seen_codes.add(code)

        name = row["名称"]
        if not isinstance(name, str) or not name.strip():
            return (
                f"Eastmoney Hong Kong-index spot row {index} field '名称' must be "
                "a non-empty string"
            )

        for field in _MARKET_QUOTE_HK_INDEX_SPOT_EM_NUMERIC_FIELDS:
            value = row[field]
            if value is None:
                continue
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    f"Eastmoney Hong Kong-index spot row {index} field {field!r} "
                    "must be numeric or null"
                )
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    f"Eastmoney Hong Kong-index spot row {index} field {field!r} "
                    "must be numeric or null"
                )
            if not math.isfinite(numeric):
                return (
                    f"Eastmoney Hong Kong-index spot row {index} field {field!r} "
                    "must be finite or null"
                )
    return None


