def _hk_index_daily_sina_history_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
) -> tuple[str | None, list[date]]:
    """Return strict-schema errors for Sina Hong Kong-index daily rows."""

    observation_dates: list[date] = []
    previous_date: date | None = None
    for index, row in enumerate(rows):
        missing = [
            field
            for field in _MARKET_HISTORY_HK_INDEX_DAILY_SINA_FIELDS
            if field not in row
        ]
        unexpected = [
            field
            for field in row
            if field not in _MARKET_HISTORY_HK_INDEX_DAILY_SINA_FIELD_SET
        ]
        if missing:
            return (
                f"Sina Hong Kong-index daily-history row {index} is missing "
                "field(s): "
                + ", ".join(missing),
                [],
            )
        if unexpected:
            return (
                f"Sina Hong Kong-index daily-history row {index} contains "
                "unsupported field(s): "
                + ", ".join(unexpected),
                [],
            )
        if tuple(row) != _MARKET_HISTORY_HK_INDEX_DAILY_SINA_FIELDS:
            return (
                "Sina Hong Kong-index daily-history rows must preserve the "
                "documented field order",
                [],
            )

        observation_date = _parse_date_value(row["date"])
        if observation_date is None:
            return (
                f"Sina Hong Kong-index daily-history row {index} has an invalid date",
                [],
            )
        if previous_date is not None:
            if observation_date == previous_date:
                return (
                    "Sina Hong Kong-index daily-history response has duplicate date "
                    f"{observation_date.isoformat()!r}",
                    [],
                )
            if observation_date < previous_date:
                return (
                    "Sina Hong Kong-index daily-history response date values must be "
                    "strictly ascending",
                    [],
                )
        previous_date = observation_date
        observation_dates.append(observation_date)

        for field in _MARKET_HISTORY_HK_INDEX_DAILY_SINA_NUMERIC_FIELDS:
            value = row[field]
            if value is None:
                continue
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    f"Sina Hong Kong-index daily-history row {index} field {field!r} "
                    "must be numeric or null",
                    [],
                )
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    f"Sina Hong Kong-index daily-history row {index} field {field!r} "
                    "must be numeric or null",
                    [],
                )
            if not math.isfinite(numeric):
                return (
                    f"Sina Hong Kong-index daily-history row {index} field {field!r} "
                    "must be finite or null",
                    [],
                )
    return None, observation_dates


