def _market_activity_hot_rank_detail_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef | None = None,
) -> tuple[str | None, list[date]]:
    """Return strict-schema errors for one A-share historical rank response."""

    observation_dates: list[date] = []
    previous_date: date | None = None
    for index, row in enumerate(rows):
        missing = sorted(set(_MARKET_ACTIVITY_HOT_RANK_DETAIL_FIELDS) - set(row))
        unexpected = sorted(set(row) - set(_MARKET_ACTIVITY_HOT_RANK_DETAIL_FIELDS))
        if missing:
            return (
                f"market-activity A-share hot-rank-detail row {index} is missing "
                "field(s): "
                + ", ".join(missing),
                [],
            )
        if unexpected:
            return (
                f"market-activity A-share hot-rank-detail row {index} contains "
                "unsupported field(s): "
                + ", ".join(unexpected),
                [],
            )
        if tuple(row) != _MARKET_ACTIVITY_HOT_RANK_DETAIL_FIELDS:
            return (
                f"market-activity A-share hot-rank-detail row {index} must preserve "
                "the official field order",
                [],
            )

        raw_date = row["时间"]
        if (
            not isinstance(raw_date, str)
            or not re.fullmatch(r"\d{4}-\d{2}-\d{2}", raw_date.strip())
        ):
            return (
                f"market-activity A-share hot-rank-detail row {index} has an invalid 时间",
                [],
            )
        observation_date = _parse_date_value(raw_date)
        if observation_date is None:
            return (
                f"market-activity A-share hot-rank-detail row {index} has an invalid 时间",
                [],
            )
        if previous_date is not None and observation_date <= previous_date:
            if observation_date == previous_date:
                return (
                    "market-activity A-share hot-rank-detail response has duplicate 时间 "
                    f"{observation_date.isoformat()!r}",
                    [],
                )
            return (
                "market-activity A-share hot-rank-detail response 时间 values must be "
                "strictly ascending",
                [],
            )
        previous_date = observation_date
        observation_dates.append(observation_date)

        row_listing = _market_activity_hot_rank_row_listing(row["证券代码"])
        if row_listing is None:
            return (
                f"market-activity A-share hot-rank-detail row {index} has an invalid 证券代码",
                [],
            )
        if listing is not None and row_listing.canonical_id != listing.canonical_id:
            return (
                f"market-activity A-share hot-rank-detail row {index} entity "
                f"{row_listing.canonical_id!r} does not match requested listing "
                f"{listing.canonical_id!r}",
                [],
            )

        rank = row["排名"]
        if isinstance(rank, bool) or not isinstance(rank, Integral) or rank <= 0:
            return (
                f"market-activity A-share hot-rank-detail row {index} field '排名' "
                "must be a positive integer",
                [],
            )

        for field in _MARKET_ACTIVITY_HOT_RANK_DETAIL_RATIO_FIELDS:
            value = row[field]
            if value is None:
                continue
            if isinstance(value, bool) or not isinstance(value, Real):
                return (
                    f"market-activity A-share hot-rank-detail row {index} field "
                    f"{field!r} must be numeric or null",
                    [],
                )
            try:
                numeric = float(value)
            except (OverflowError, TypeError, ValueError):
                return (
                    f"market-activity A-share hot-rank-detail row {index} field "
                    f"{field!r} must be numeric or null",
                    [],
                )
            if not math.isfinite(numeric):
                return (
                    f"market-activity A-share hot-rank-detail row {index} field "
                    f"{field!r} must be finite or null",
                    [],
                )
            if not 0 <= numeric <= 1:
                return (
                    f"market-activity A-share hot-rank-detail row {index} field "
                    f"{field!r} must be between 0 and 1 or null",
                    [],
                )

    return None, observation_dates


