def _management_person_row_validation_error(
    row: Mapping[str, JSONValue],
    index: int,
    *,
    listing: _ListingRef,
    name: str,
) -> tuple[str | None, date | None]:
    """Return a strict-schema error and the row's change date."""

    if tuple(row) != _INSIDER_MANAGEMENT_PERSON_FIELDS:
        return (
            f"management-person row {index} has an unexpected field schema or order",
            None,
        )

    code = row["代码"]
    if not isinstance(code, str) or re.fullmatch(r"\d{6}", code) is None:
        return (
            f"management-person row {index} has an invalid 代码",
            None,
        )
    if code != listing.code:
        return (
            f"management-person row entity {code!r} does not match requested "
            f"listing {listing.canonical_id!r}",
            None,
        )

    for field in _INSIDER_MANAGEMENT_PERSON_TEXT_FIELDS:
        value = row[field]
        if value is None:
            if field in {"代码", "变动人"}:
                return (
                    f"management-person row {index} field {field!r} "
                    "must be non-empty text",
                    None,
                )
            continue
        if not isinstance(value, str):
            return (
                f"management-person row {index} field {field!r} "
                "must be text or null",
                None,
            )
        if not value.strip():
            return (
                f"management-person row {index} field {field!r} "
                "must be non-empty text or null",
                None,
            )

    if row["变动人"] != name:
        return (
            f"management-person row {index} person {row['变动人']!r} does not match "
            f"requested name {name!r}",
            None,
        )

    raw_date = row["日期"]
    if not isinstance(raw_date, str):
        return (
            f"management-person row {index} field '日期' must be an ISO date string",
            None,
        )
    observation_date = _parse_date_value(raw_date)
    if observation_date is None:
        return (
            f"management-person row {index} has an invalid 日期",
            None,
        )

    for field in _INSIDER_MANAGEMENT_PERSON_NUMERIC_FIELDS:
        value = row[field]
        if value is None:
            continue
        if isinstance(value, bool) or not isinstance(value, Real):
            return (
                f"management-person row {index} field {field!r} "
                "must be numeric or null",
                None,
            )
        try:
            numeric = float(value)
        except (OverflowError, TypeError, ValueError):
            return (
                f"management-person row {index} field {field!r} "
                "must be numeric or null",
                None,
            )
        if not math.isfinite(numeric):
            return (
                f"management-person row {index} field {field!r} "
                "must be finite or null",
                None,
            )
        if field in _INSIDER_MANAGEMENT_PERSON_NON_NEGATIVE_FIELDS and numeric < 0:
            return (
                f"management-person row {index} field {field!r} "
                "must be non-negative or null",
                None,
            )

    return None, observation_date


def _management_person_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
    *,
    listing: _ListingRef,
    name: str,
) -> tuple[str | None, list[date]]:
    """Validate the source-shaped management-person response."""

    observation_dates: list[date] = []
    for index, row in enumerate(rows):
        message, observation_date = _management_person_row_validation_error(
            row,
            index,
            listing=listing,
            name=name,
        )
        if message is not None:
            return message, []
        assert observation_date is not None
        observation_dates.append(observation_date)
    return None, observation_dates


def _validate_insider_management_person_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    name: object,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> tuple[date | None, date | None]:
    """Validate the symbol/person-scoped management history before storage."""

    if not isinstance(name, str) or not name.strip():
        raise ProviderResponseError(
            f"AKShare management-person name is not a non-empty string for "
            f"{request.entity_id!r}",
            provider=provider,
            request=request,
        )
    message, observation_dates = _management_person_validation_message(
        rows,
        listing=listing,
        name=name,
    )
    if message is not None:
        raise ProviderResponseError(
            f"AKShare {message} for {request.entity_id!r}",
            provider=provider,
            request=request,
        )
    return (
        min(observation_dates) if observation_dates else None,
        max(observation_dates) if observation_dates else None,
    )


def _validate_insider_management_person_normalizer_scope(
    record: RawProviderRecord,
    listing: _ListingRef,
    rows: Sequence[Mapping[str, JSONValue]],
) -> None:
    """Validate management-person endpoint, identity and replay metadata."""

    if listing.market is not ListingMarket.A:
        raise ProviderNormalizationError(
            "AKShare management-person raw slice supports A-share listings only"
        )
    if record.response_metadata.get("endpoint") != "stock_hold_management_person_em":
        raise ProviderNormalizationError(
            "AKShare management-person record must come from "
            "stock_hold_management_person_em"
        )
    if record.source_uri != _SOURCE_URIS["stock_hold_management_person_em"]:
        raise ProviderNormalizationError(
            "AKShare management-person source URI does not match the documented endpoint"
        )
    try:
        upstream_kwargs = _insider_share_change_kwargs(
            "stock_hold_management_person_em",
            listing,
            record.request,
        )
    except ProviderRequestError as exc:
        raise ProviderNormalizationError(str(exc)) from exc

    name = upstream_kwargs["name"]
    if not isinstance(name, str):
        raise ProviderNormalizationError(
            "AKShare management-person upstream name is not text"
        )
    message, observation_dates = _management_person_validation_message(
        rows,
        listing=listing,
        name=name,
    )
    if message is not None:
        raise ProviderNormalizationError(message)

    expected_metadata: dict[str, JSONValue] = {
        "endpoint": "stock_hold_management_person_em",
        "market": ListingMarket.A.value,
        "listing_code": listing.code,
        "management_person_view": _INSIDER_MANAGEMENT_PERSON_VIEW,
        "upstream_symbol": listing.code,
        "upstream_name": name,
        "market_scope": "requested_a_share_listing",
        "listing_scoped_request": True,
        "row_filtering": "upstream",
        "snapshot_scope": "historical_published_person_dataset",
        "date_binding": "row_change_dates",
        "observation_date_field": "日期",
        "observation_date_fields": list(_INSIDER_MANAGEMENT_PERSON_DATE_FIELDS),
        "field_count": len(_INSIDER_MANAGEMENT_PERSON_FIELDS),
        "source_field_order": list(_INSIDER_MANAGEMENT_PERSON_FIELDS),
        "text_fields": list(_INSIDER_MANAGEMENT_PERSON_TEXT_FIELDS),
        "date_fields": list(_INSIDER_MANAGEMENT_PERSON_DATE_FIELDS),
        "value_fields": list(_INSIDER_MANAGEMENT_PERSON_NUMERIC_FIELDS),
        "non_negative_fields": sorted(_INSIDER_MANAGEMENT_PERSON_NON_NEGATIVE_FIELDS),
        "undocumented_numeric_units": dict(
            _INSIDER_MANAGEMENT_PERSON_UNDOCUMENTED_NUMERIC_UNITS
        ),
        "upstream_page_size": 5000,
        "entity_rows_selected": True,
        "entity_row_count": len(rows),
    }
    for name_key, expected in expected_metadata.items():
        if name_key not in record.response_metadata:
            matches = False
        elif name_key in {"listing_scoped_request", "entity_rows_selected"}:
            actual = record.response_metadata[name_key]
            matches = isinstance(actual, bool) and actual is expected
        elif name_key in {"field_count", "entity_row_count", "upstream_page_size"}:
            actual = record.response_metadata[name_key]
            matches = (
                isinstance(actual, int)
                and not isinstance(actual, bool)
                and actual == expected
            )
        else:
            matches = record.response_metadata[name_key] == expected
        if not matches:
            raise ProviderNormalizationError(
                "AKShare management-person response metadata "
                f"{name_key!r} does not match the requested replay scope"
            )

    upstream_count = record.response_metadata.get("upstream_row_count")
    if (
        not isinstance(upstream_count, int)
        or isinstance(upstream_count, bool)
        or upstream_count != len(rows)
    ):
        raise ProviderNormalizationError(
            "AKShare management-person response metadata "
            "'upstream_row_count' does not match the requested replay scope"
        )

    expected_start = min(observation_dates).isoformat() if observation_dates else None
    expected_end = max(observation_dates).isoformat() if observation_dates else None
    for name_key, expected in (
        ("observation_start_date", expected_start),
        ("observation_end_date", expected_end),
    ):
        if record.response_metadata.get(name_key) != expected:
            raise ProviderNormalizationError(
                "AKShare management-person response metadata "
                f"{name_key!r} does not match the requested replay scope"
            )


def _executive_share_changes_row_validation_error(
    row: Mapping[str, JSONValue],
    index: int,
    *,
    direction: str,
) -> tuple[str | None, date | None]:
    """Return a strict-schema error and the row's cutoff date."""

    if tuple(row) != _EXECUTIVE_SHARE_CHANGES_FIELDS:
        return (
            f"executive share-change row {index} has an unexpected field "
            "schema or order",
            None,
        )

    code = row["代码"]
    if not isinstance(code, str) or re.fullmatch(r"\d{6}", code) is None:
        return (
            f"executive share-change row {index} has an invalid 代码",
            None,
        )

    for field in _EXECUTIVE_SHARE_CHANGES_TEXT_FIELDS:
        value = row[field]
        if value is None:
            if field in {"代码", "持股变动信息-增减"}:
                return (
                    f"executive share-change row {index} field {field!r} "
                    "must be non-empty text",
                    None,
                )
            continue
        if not isinstance(value, str):
            return (
                f"executive share-change row {index} field {field!r} "
                "must be text or null",
                None,
            )
        if not value.strip():
            return (
                f"executive share-change row {index} field {field!r} "
                "must be non-empty text or null",
                None,
            )

    row_direction = row["持股变动信息-增减"]
    if row_direction not in _EXECUTIVE_SHARE_CHANGES_ROW_DIRECTIONS:
        choices = ", ".join(sorted(_EXECUTIVE_SHARE_CHANGES_ROW_DIRECTIONS))
        return (
            f"executive share-change row {index} has an invalid direction; "
            f"expected one of: {choices}",
            None,
        )
    expected_row_direction = {
        "股东增持": "增持",
        "股东减持": "减持",
    }.get(direction)
    if expected_row_direction is not None and row_direction != expected_row_direction:
        return (
            f"executive share-change row {index} direction {row_direction!r} does not "
            f"match requested {direction!r}",
            None,
        )

    cutoff_date: date | None = None
    for field in _EXECUTIVE_SHARE_CHANGES_DATE_FIELDS:
        value = row[field]
        if value is None:
            continue
        if not isinstance(value, str):
            return (
                f"executive share-change row {index} field {field!r} "
                "must be an ISO date string or null",
                None,
            )
        parsed = _parse_date_value(value)
        if parsed is None:
            return (
                f"executive share-change row {index} has an invalid {field}",
                None,
            )
        if field == "变动截止日":
            cutoff_date = parsed

    for field in _EXECUTIVE_SHARE_CHANGES_NUMERIC_FIELDS:
        value = row[field]
        if value is None:
            continue
        if isinstance(value, bool) or not isinstance(value, Real):
            return (
                f"executive share-change row {index} field {field!r} "
                "must be numeric or null",
                None,
            )
        try:
            numeric = float(value)
        except (OverflowError, TypeError, ValueError):
            return (
                f"executive share-change row {index} field {field!r} "
                "must be numeric or null",
                None,
            )
        if not math.isfinite(numeric):
            return (
                f"executive share-change row {index} field {field!r} "
                "must be finite or null",
                None,
            )
        if field in _EXECUTIVE_SHARE_CHANGES_NON_NEGATIVE_FIELDS and numeric < 0:
            return (
                f"executive share-change row {index} field {field!r} "
                "must be non-negative or null",
                None,
            )

    return None, cutoff_date


def _executive_share_changes_validation_message(
    rows: Sequence[Mapping[str, JSONValue]],
    *,
    direction: str,
) -> tuple[str | None, list[date]]:
    """Validate the source-shaped executive/shareholder-change response."""

    cutoff_dates: list[date] = []
    for index, row in enumerate(rows):
        message, cutoff_date = _executive_share_changes_row_validation_error(
            row,
            index,
            direction=direction,
        )
        if message is not None:
            return message, []
        if cutoff_date is not None:
            cutoff_dates.append(cutoff_date)
    return None, cutoff_dates


def _cninfo_management_detail_row_validation_error(
    row: Mapping[str, JSONValue],
    index: int,
) -> tuple[str | None, date | None]:
    """Return a strict-schema error and parsed cutoff date for one CNINFO row."""

    if tuple(row) != _INSIDER_CNINFO_MANAGEMENT_DETAIL_FIELDS:
        return (
            f"CNINFO management-holding row {index} has an unexpected field "
            "schema or order",
            None,
        )

    code = row["证券代码"]
    if not isinstance(code, str) or re.fullmatch(r"\d{6}", code) is None:
        return (
            f"CNINFO management-holding row {index} has an invalid 证券代码",
            None,
        )

    for field in _INSIDER_CNINFO_MANAGEMENT_DETAIL_TEXT_FIELDS:
        value = row[field]
        if value is not None and not isinstance(value, str):
            return (
                f"CNINFO management-holding row {index} field {field!r} "
                "must be text or null",
                None,
            )

    observation_dates: dict[str, date | None] = {}
    for field in _INSIDER_CNINFO_MANAGEMENT_DETAIL_DATE_FIELDS:
        value = row[field]
        if value is None:
            if field == "截止日期":
                return (
                    f"CNINFO management-holding row {index} has no {field}",
                    None,
                )
            observation_dates[field] = None
            continue
        if not isinstance(value, str):
            return (
                f"CNINFO management-holding row {index} field {field!r} "
                "must be an ISO date string or null",
                None,
            )
        parsed = _parse_date_value(value)
        if parsed is None:
            return (
                f"CNINFO management-holding row {index} has an invalid {field}",
                None,
            )
        observation_dates[field] = parsed

    for field in _INSIDER_CNINFO_MANAGEMENT_DETAIL_NUMERIC_FIELDS:
        value = row[field]
        if value is None:
            continue
        if isinstance(value, bool) or not isinstance(value, Real):
            return (
                f"CNINFO management-holding row {index} field {field!r} "
                "must be numeric or null",
                None,
            )
        numeric = float(value)
        if not math.isfinite(numeric):
            return (
                f"CNINFO management-holding row {index} field {field!r} "
                "must be finite or null",
                None,
            )
        if (
            field in _INSIDER_CNINFO_MANAGEMENT_DETAIL_NONNEGATIVE_FIELDS
            and numeric < 0
        ):
            return (
                f"CNINFO management-holding row {index} field {field!r} "
                "must be non-negative or null",
                None,
            )

    return None, observation_dates["截止日期"]


def _validate_insider_cninfo_management_detail_normalizer_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
) -> list[date]:
    """Validate replayed CNINFO management-detail rows inside the listing boundary."""

    cutoff_dates: list[date] = []
    for index, row in enumerate(rows):
        message, cutoff_date = _cninfo_management_detail_row_validation_error(
            row,
            index,
        )
        if message is not None:
            raise ProviderNormalizationError(message)
        row_code = row["证券代码"]
        if row_code != listing.code:
            raise ProviderNormalizationError(
                f"CNINFO management-holding row entity {row_code!r} does not match "
                f"requested listing {listing.canonical_id!r}"
            )
        if cutoff_date is not None:
            cutoff_dates.append(cutoff_date)
    return cutoff_dates


def _validate_insider_cninfo_management_detail_normalizer_scope(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    record: RawProviderRecord,
) -> None:
    """Validate CNINFO endpoint, direction, schema and replay metadata."""

    cutoff_dates = _validate_insider_cninfo_management_detail_normalizer_rows(
        rows,
        listing,
    )
    try:
        upstream_kwargs = _insider_share_change_kwargs(
            "stock_hold_management_detail_cninfo",
            listing,
            record.request,
        )
    except ProviderRequestError as exc:
        raise ProviderNormalizationError(str(exc)) from exc

    if record.source_uri != _SOURCE_URIS["stock_hold_management_detail_cninfo"]:
        raise ProviderNormalizationError(
            "AKShare CNINFO management-holding source URI does not match the "
            "documented endpoint"
        )

    direction = upstream_kwargs["symbol"]
    expected_metadata: dict[str, JSONValue] = {
        "endpoint": "stock_hold_management_detail_cninfo",
        "market": ListingMarket.A.value,
        "listing_code": listing.code,
        "management_view": _INSIDER_CNINFO_MANAGEMENT_DETAIL_VIEW,
        "management_direction": direction,
        "upstream_direction": direction,
        "upstream_symbol": direction,
        "listing_scoped_request": False,
        "row_filtering": "provider",
        "snapshot_scope": "upstream_rolling_prior_year_to_request_date",
        "date_binding": "upstream_rolling_window",
        "observation_date_field": "截止日期",
        "observation_date_fields": list(
            _INSIDER_CNINFO_MANAGEMENT_DETAIL_DATE_FIELDS
        ),
        "field_count": len(_INSIDER_CNINFO_MANAGEMENT_DETAIL_FIELDS),
        "source_field_order": list(_INSIDER_CNINFO_MANAGEMENT_DETAIL_FIELDS),
        "quantity_unit": "万股",
        "price_unit": "元",
        "market_value_unit": "万元",
        "ratio_unit": "%",
        "entity_rows_selected": True,
        "entity_row_count": len(rows),
    }
    for name, expected in expected_metadata.items():
        if name not in record.response_metadata:
            matches = False
        elif name in {"listing_scoped_request", "entity_rows_selected"}:
            actual = record.response_metadata[name]
            matches = isinstance(actual, bool) and actual is expected
        elif name == "entity_row_count":
            actual = record.response_metadata[name]
            matches = (
                isinstance(actual, int)
                and not isinstance(actual, bool)
                and actual == expected
            )
        else:
            matches = record.response_metadata[name] == expected
        if not matches:
            raise ProviderNormalizationError(
                "AKShare CNINFO management-holding response metadata "
                f"{name!r} does not match the requested replay scope"
            )

    upstream_count = record.response_metadata.get("upstream_row_count")
    if (
        not isinstance(upstream_count, int)
        or isinstance(upstream_count, bool)
        or upstream_count < len(rows)
    ):
        raise ProviderNormalizationError(
            "AKShare CNINFO management-holding response metadata "
            "'upstream_row_count' does not match the requested replay scope"
        )

    for name in ("observation_start_date", "observation_end_date"):
        actual = record.response_metadata.get(name)
        actual_date = _parse_date_value(actual) if actual is not None else None
        if actual is not None and actual_date is None:
            raise ProviderNormalizationError(
                "AKShare CNINFO management-holding response metadata "
                f"{name!r} is not a valid date"
            )
        if not cutoff_dates:
            # Provider filtering may legitimately leave no rows for the requested
            # listing while the full upstream snapshot still has date bounds.
            continue
        if actual_date is None:
            raise ProviderNormalizationError(
                "AKShare CNINFO management-holding response metadata "
                f"{name!r} does not cover the selected row dates"
            )
        if actual_date is not None:
            boundary_ok = (
                actual_date <= min(cutoff_dates)
                if name == "observation_start_date"
                else actual_date >= max(cutoff_dates)
            )
            if not boundary_ok:
                raise ProviderNormalizationError(
                    "AKShare CNINFO management-holding response metadata "
                    f"{name!r} does not cover the selected row dates"
                )


