def _top10_rank_value(raw_value: object) -> int | None:
    if raw_value is None or isinstance(raw_value, bool):
        return None
    if isinstance(raw_value, Real):
        numeric = float(raw_value)
    else:
        text = str(raw_value).strip()
        if text.lower() in _MISSING_TEXT:
            return None
        try:
            numeric = float(text.replace(",", ""))
        except ValueError:
            return None
    if not math.isfinite(numeric) or not numeric.is_integer() or numeric < 1:
        return None
    return int(numeric)


def _validate_shareholder_free_holding_detail_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    report_period: date,
    provider: ProviderIdentity,
    request: ProviderRequest,
) -> None:
    """Validate the full tradable-holder detail universe before filtering."""

    for row in rows:
        if _row_code(row, ListingMarket.A) is None:
            raise ProviderResponseError(
                f"AKShare returned a free-holding-detail row without a listing code for "
                f"{request.entity_id!r}",
                provider=provider,
                request=request,
            )
        found_holder, raw_holder = _lookup(
            row,
            _SHAREHOLDER_FREE_HOLDING_DETAIL_HOLDER_FIELDS,
        )
        if not found_holder or _text_value(raw_holder) is None:
            raise ProviderResponseError(
                f"AKShare returned a free-holding-detail row without a holder name for "
                f"{request.entity_id!r}",
                provider=provider,
                request=request,
            )
        found_period, raw_period = _lookup(
            row,
            _SHAREHOLDER_FREE_HOLDING_DETAIL_PERIOD_FIELDS,
        )
        if not found_period or _text_value(raw_period) is None:
            raise ProviderResponseError(
                f"AKShare returned a free-holding-detail row without a report period for "
                f"{request.entity_id!r}",
                provider=provider,
                request=request,
            )
        row_period = _parse_date_value(raw_period)
        if row_period is None:
            raise ProviderResponseError(
                f"AKShare returned an invalid free-holding-detail report period for "
                f"{request.entity_id!r}",
                provider=provider,
                request=request,
            )
        if row_period != report_period:
            raise ProviderResponseError(
                f"AKShare returned free-holding-detail row period "
                f"{row_period.isoformat()!r}; requested {report_period.isoformat()!r}",
                provider=provider,
                request=request,
            )
        found_announcement, raw_announcement = _lookup(
            row,
            _SHAREHOLDER_FREE_HOLDING_DETAIL_ANNOUNCEMENT_FIELDS,
        )
        if (
            found_announcement
            and _text_value(raw_announcement) is not None
            and _parse_date_value(raw_announcement) is None
        ):
            raise ProviderResponseError(
                f"AKShare returned an invalid free-holding-detail announcement date for "
                f"{request.entity_id!r}",
                provider=provider,
                request=request,
            )


def _validate_shareholder_top10_provider_rows(
    rows: Sequence[Mapping[str, JSONValue]],
    listing: _ListingRef,
    *,
    provider: ProviderIdentity,
    request: ProviderRequest,
    label: str = "top-ten-shareholder",
) -> None:
    """Validate identity fields in a symbol-scoped ranked-holder response."""

    seen_ranks: set[int] = set()
    for row in rows:
        row_code = _row_code(row, ListingMarket.A)
        if row_code is not None and row_code != listing.code:
            raise ProviderResponseError(
                f"AKShare returned a {label} row entity {row_code!r} "
                f"for requested listing {listing.canonical_id!r}",
                provider=provider,
                request=request,
            )
        found_rank, raw_rank = _lookup(row, _SHAREHOLDER_TOP10_RANK_FIELDS)
        rank = _top10_rank_value(raw_rank) if found_rank else None
        if rank is None:
            raise ProviderResponseError(
                f"AKShare returned a {label} row without a valid rank "
                f"for {request.entity_id!r}",
                provider=provider,
                request=request,
            )
        if rank in seen_ranks:
            raise ProviderResponseError(
                f"AKShare returned duplicate {label} rank {rank!r} "
                f"for {request.entity_id!r}",
                provider=provider,
                request=request,
            )
        found_holder, raw_holder = _lookup(row, _SHAREHOLDER_TOP10_HOLDER_FIELDS)
        if not found_holder or _text_value(raw_holder) is None:
            raise ProviderResponseError(
                f"AKShare returned a {label} row without a holder name "
                f"for {request.entity_id!r}",
                provider=provider,
                request=request,
            )
        seen_ranks.add(rank)


