def _market_activity_date_parameter(
    raw_value: object,
    *,
    name: str,
    request: ProviderRequest,
) -> date:
    if not isinstance(raw_value, str) or not re.fullmatch(r"\d{8}", raw_value):
        raise ProviderRequestError(
            f"market-activity {name} must be YYYYMMDD",
            request=request,
            retryable=False,
        )
    try:
        return datetime.strptime(raw_value, "%Y%m%d").date()
    except ValueError as exc:
        raise ProviderRequestError(
            f"market-activity {name} must be a valid YYYYMMDD date",
            request=request,
            retryable=False,
        ) from exc


def _market_activity_month_parameter(
    raw_value: object,
    *,
    name: str,
    request: ProviderRequest,
) -> date:
    if not isinstance(raw_value, str) or not re.fullmatch(r"\d{6}", raw_value):
        raise ProviderRequestError(
            f"market-activity {name} must be YYYYMM",
            request=request,
            retryable=False,
        )
    try:
        return datetime.strptime(raw_value, "%Y%m").date()
    except ValueError as exc:
        raise ProviderRequestError(
            f"market-activity {name} must be a valid YYYYMM month",
            request=request,
            retryable=False,
        ) from exc


def _market_activity_date_range(request: ProviderRequest) -> tuple[date, date]:
    if not {"start_date", "end_date"}.issubset(request.parameters):
        raise ProviderRequestError(
            "the AKShare market-activity endpoint requires start_date and end_date "
            "(YYYYMMDD)",
            request=request,
            retryable=False,
        )
    start_date = _market_activity_date_parameter(
        request.parameters["start_date"],
        name="start_date",
        request=request,
    )
    end_date = _market_activity_date_parameter(
        request.parameters["end_date"],
        name="end_date",
        request=request,
    )
    if start_date > end_date:
        raise ProviderRequestError(
            "market-activity start_date must not be after end_date",
            request=request,
            retryable=False,
        )
    return start_date, end_date


def _market_activity_hsgt_board_rank_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    """Build the documented northbound HSGT board-rank request."""

    if endpoint_name != _MARKET_ACTIVITY_HSGT_BOARD_RANK_ENDPOINT:
        raise ProviderRequestError(
            "unsupported AKShare HSGT board-rank endpoint "
            f"{endpoint_name!r}",
            request=request,
            retryable=False,
        )
    if listing.market is not ListingMarket.A:
        raise ProviderRequestError(
            "the AKShare HSGT board-rank endpoint supports A-share listings only",
            request=request,
            retryable=False,
        )
    unknown = sorted(
        set(request.parameters) - _MARKET_ACTIVITY_HSGT_BOARD_RANK_PARAMETER_NAMES
    )
    if unknown:
        raise ProviderRequestError(
            "unsupported AKShare HSGT board-rank parameter(s): "
            + ", ".join(unknown),
            request=request,
            retryable=False,
        )
    if request.parameters.get("view") != _MARKET_ACTIVITY_HSGT_BOARD_RANK_VIEW:
        raise ProviderRequestError(
            "the AKShare HSGT board-rank endpoint requires "
            f"view={_MARKET_ACTIVITY_HSGT_BOARD_RANK_VIEW!r}",
            request=request,
            retryable=False,
        )
    symbol = request.parameters.get("symbol")
    if (
        not isinstance(symbol, str)
        or symbol not in _MARKET_ACTIVITY_HSGT_BOARD_RANK_SYMBOL_SET
    ):
        raise ProviderRequestError(
            "AKShare HSGT board-rank symbol must be one of: "
            + ", ".join(_MARKET_ACTIVITY_HSGT_BOARD_RANK_SYMBOLS),
            request=request,
            retryable=False,
        )
    indicator = request.parameters.get("indicator")
    if (
        not isinstance(indicator, str)
        or indicator not in _MARKET_ACTIVITY_HSGT_BOARD_RANK_INDICATOR_SET
    ):
        raise ProviderRequestError(
            "AKShare HSGT board-rank indicator must be one of: "
            + ", ".join(_MARKET_ACTIVITY_HSGT_BOARD_RANK_INDICATORS),
            request=request,
            retryable=False,
        )
    return {"symbol": symbol, "indicator": indicator}


