def _market_activity_hot_rank_latest_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    """Build a documented A/H symbol-scoped latest popularity-rank request."""

    if endpoint_name not in _MARKET_ACTIVITY_HOT_RANK_LATEST_ENDPOINTS:
        raise ProviderRequestError(
            "unsupported AKShare market-activity latest-hot-rank endpoint "
            f"{endpoint_name!r}",
            request=request,
            retryable=False,
        )
    expected_market = (
        ListingMarket.H
        if endpoint_name == "stock_hk_hot_rank_latest_em"
        else ListingMarket.A
    )
    if listing.market is not expected_market:
        raise ProviderRequestError(
            "the AKShare market-activity latest-hot-rank endpoint supports A-share "
            "listings only"
            if expected_market is ListingMarket.A
            else "H-share listings only",
            request=request,
            retryable=False,
        )
    unknown = sorted(
        set(request.parameters) - _MARKET_ACTIVITY_HOT_RANK_LATEST_PARAMETER_NAMES
    )
    if unknown:
        raise ProviderRequestError(
            "unsupported AKShare market-activity latest-hot-rank parameter(s): "
            + ", ".join(unknown),
            request=request,
            retryable=False,
        )
    if request.parameters.get("view") != _MARKET_ACTIVITY_HOT_RANK_LATEST_VIEW:
        raise ProviderRequestError(
            "the AKShare market-activity latest-hot-rank endpoint requires "
            f"view={_MARKET_ACTIVITY_HOT_RANK_LATEST_VIEW!r}",
            request=request,
            retryable=False,
        )
    return {
        "symbol": (
            listing.canonical_id
            if expected_market is ListingMarket.A
            else listing.code
        )
    }


