def _capital_flow_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    """Build the documented capital-flow request for each endpoint."""

    if endpoint_name == _CAPITAL_FLOW_HSGT_SUMMARY_ENDPOINT:
        if listing.market not in {ListingMarket.A, ListingMarket.H}:
            raise ProviderRequestError(
                "the AKShare HSGT fund-flow-summary endpoint supports A- and H-share "
                "listing context only",
                request=request,
                retryable=False,
            )
        unknown = sorted(
            set(request.parameters) - _CAPITAL_FLOW_HSGT_SUMMARY_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare HSGT fund-flow-summary parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _CAPITAL_FLOW_HSGT_SUMMARY_VIEW:
            raise ProviderRequestError(
                "the AKShare HSGT fund-flow-summary endpoint requires "
                f"view={_CAPITAL_FLOW_HSGT_SUMMARY_VIEW!r}",
                request=request,
                retryable=False,
            )
        return {}

    if endpoint_name == _CAPITAL_FLOW_HSGT_HIST_ENDPOINT:
        unknown = sorted(
            set(request.parameters) - _CAPITAL_FLOW_HSGT_HIST_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare HSGT historical-flow parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _CAPITAL_FLOW_HSGT_HIST_VIEW:
            raise ProviderRequestError(
                "the AKShare HSGT historical-flow endpoint requires "
                f"view={_CAPITAL_FLOW_HSGT_HIST_VIEW!r}",
                request=request,
                retryable=False,
            )
        symbol = request.parameters.get("symbol")
        if (
            not isinstance(symbol, str)
            or symbol not in _CAPITAL_FLOW_HSGT_HIST_SYMBOL_SET
        ):
            raise ProviderRequestError(
                "HSGT historical-flow symbol must be one of: "
                + ", ".join(_CAPITAL_FLOW_HSGT_HIST_SYMBOLS),
                request=request,
                retryable=False,
            )
        expected_market = _CAPITAL_FLOW_HSGT_HIST_DIRECTION_MARKETS[symbol]
        if listing.market is not expected_market:
            direction = (
                "northbound" if expected_market is ListingMarket.A else "southbound"
            )
            market_label = "A-share" if expected_market is ListingMarket.A else "H-share"
            raise ProviderRequestError(
                f"the AKShare HSGT {direction} historical-flow endpoint supports "
                f"{market_label} listing context only",
                request=request,
                retryable=False,
            )
        return {"symbol": symbol}

    if endpoint_name == _CAPITAL_FLOW_HSGT_FUND_MIN_ENDPOINT:
        unknown = sorted(
            set(request.parameters) - _CAPITAL_FLOW_HSGT_FUND_MIN_PARAMETER_NAMES
        )
        if unknown:
            raise ProviderRequestError(
                "unsupported AKShare HSGT minute-fund-flow parameter(s): "
                + ", ".join(unknown),
                request=request,
                retryable=False,
            )
        if request.parameters.get("view") != _CAPITAL_FLOW_HSGT_FUND_MIN_VIEW:
            raise ProviderRequestError(
                "the AKShare HSGT minute-fund-flow endpoint requires "
                f"view={_CAPITAL_FLOW_HSGT_FUND_MIN_VIEW!r}",
                request=request,
                retryable=False,
            )
        symbol = request.parameters.get("symbol")
        if (
            not isinstance(symbol, str)
            or symbol not in _CAPITAL_FLOW_HSGT_FUND_MIN_SYMBOL_SET
        ):
            raise ProviderRequestError(
                "HSGT minute-fund-flow symbol must be one of: "
                + ", ".join(_CAPITAL_FLOW_HSGT_FUND_MIN_SYMBOLS),
                request=request,
                retryable=False,
            )
        expected_market = _CAPITAL_FLOW_HSGT_FUND_MIN_DIRECTION_MARKETS[symbol]
        if listing.market is not expected_market:
            direction = "northbound" if symbol == "北向资金" else "southbound"
            market_label = "A-share" if expected_market is ListingMarket.A else "H-share"
            raise ProviderRequestError(
                f"the AKShare HSGT {direction} minute-fund-flow endpoint supports "
                f"{market_label} listing context only",
                request=request,
                retryable=False,
            )
        return {"symbol": symbol}

    if endpoint_name != "stock_individual_fund_flow":
        raise ProviderRequestError(
            f"unsupported AKShare capital-flow endpoint {endpoint_name!r}",
            request=request,
            retryable=False,
        )
    if listing.market is not ListingMarket.A:
        raise ProviderRequestError(
            "the AKShare individual-fund-flow endpoint supports A-share listings only",
            request=request,
            retryable=False,
        )
    unknown = sorted(set(request.parameters) - _CAPITAL_FLOW_PARAMETER_NAMES)
    if unknown:
        raise ProviderRequestError(
            "unsupported AKShare capital-flow parameter(s): " + ", ".join(unknown),
            request=request,
            retryable=False,
        )
    market_names = {"SH": "sh", "SZ": "sz", "BJ": "bj"}
    market = market_names.get(listing.canonical_id[:2])
    if market is None:
        raise ProviderRequestError(
            "the AKShare individual-fund-flow endpoint requires a mainland A-share listing",
            request=request,
            retryable=False,
        )
    return {"stock": listing.code, "market": market}


def _history_kwargs(
    endpoint_name: str,
    listing: _ListingRef,
    request: ProviderRequest,
) -> dict[str, object]:
    if endpoint_name == _MARKET_HISTORY_GLOBAL_INDEX_EM_ENDPOINT:
        return _global_index_em_history_kwargs(listing, request)
    if endpoint_name == _MARKET_HISTORY_GLOBAL_INDEX_SINA_ENDPOINT:
        return _global_index_sina_history_kwargs(listing, request)
    if endpoint_name == _MARKET_HISTORY_HK_INDEX_DAILY_EM_ENDPOINT:
        return _hk_index_daily_em_history_kwargs(listing, request)
    if endpoint_name == _MARKET_HISTORY_HK_INDEX_DAILY_SINA_ENDPOINT:
        return _hk_index_daily_sina_history_kwargs(listing, request)
    if endpoint_name == _MARKET_HISTORY_US_INDEX_SINA_ENDPOINT:
        return _us_index_sina_history_kwargs(listing, request)
    if endpoint_name == "stock_zh_b_minute":
        return _b_minute_history_kwargs(listing, request)
    if (
        endpoint_name == "stock_hk_daily"
        and request.parameters.get("view") == _MARKET_HISTORY_HK_DAILY_VIEW
    ):
        return _hk_daily_history_kwargs(listing, request)
    if endpoint_name == _MARKET_HISTORY_AH_DAILY_ENDPOINT:
        return _ah_daily_history_kwargs(listing, request)
    if endpoint_name == "stock_zh_b_daily":
        return _b_daily_history_kwargs(listing, request)
    if endpoint_name == "stock_zh_kcb_daily":
        return _kcb_daily_history_kwargs(listing, request)
    if endpoint_name == "stock_zh_index_daily":
        return _index_daily_history_kwargs(listing, request)
    if endpoint_name == "stock_intraday_sina":
        return _sina_intraday_kwargs(listing, request)
    if endpoint_name == "stock_intraday_em":
        return _intraday_trades_kwargs(listing, request)
    if endpoint_name == "stock_cyq_em":
        return _chip_distribution_kwargs(listing, request)
    if endpoint_name == "stock_zh_a_tick_tx_js":
        return _tencent_tick_kwargs(listing, request)
    if endpoint_name == "stock_zh_a_hist_tx":
        return _tencent_daily_history_kwargs(listing, request)
    if (
        endpoint_name == _MARKET_HISTORY_EASTMONEY_A_HIST_ENDPOINT
        and request.parameters.get("view")
        == _MARKET_HISTORY_EASTMONEY_A_HIST_VIEW
    ):
        return _eastmoney_a_hist_kwargs(listing, request)
    if (
        endpoint_name == _MARKET_HISTORY_EASTMONEY_HK_HIST_ENDPOINT
        and request.parameters.get("view")
        == _MARKET_HISTORY_EASTMONEY_HK_HIST_VIEW
    ):
        return _eastmoney_hk_hist_kwargs(listing, request)
    if endpoint_name == "stock_zh_index_daily_tx":
        return _tencent_index_daily_history_kwargs(listing, request)
    if endpoint_name == "stock_zh_index_daily_em":
        return _index_daily_em_history_kwargs(listing, request)
    if endpoint_name == _MARKET_HISTORY_INDEX_ZH_A_HIST_ENDPOINT:
        return _index_zh_a_hist_kwargs(listing, request)
    if endpoint_name == _MARKET_HISTORY_INDEX_ZH_A_HIST_MIN_EM_ENDPOINT:
        return _index_zh_a_hist_min_em_kwargs(listing, request)
    if endpoint_name == "stock_zh_a_cdr_daily":
        return _cdr_daily_history_kwargs(listing, request)
    if (
        endpoint_name == _MARKET_HISTORY_SINA_A_DAILY_ENDPOINT
        and request.parameters.get("view") == _MARKET_HISTORY_SINA_A_DAILY_VIEW
    ):
        return _sina_a_daily_history_kwargs(listing, request)
    if endpoint_name == "stock_zh_a_minute":
        return _sina_minute_history_kwargs(listing, request)
    if endpoint_name == "stock_hk_hist_min_em":
        return _hk_intraday_history_kwargs(listing, request)
    if endpoint_name == "stock_zh_a_hist_min_em":
        return _intraday_history_kwargs(listing, request)
    if endpoint_name == "stock_zh_a_hist_pre_min_em":
        return _pre_market_history_kwargs(listing, request)

    parameters = dict(request.parameters)
    unknown = sorted(set(parameters) - _HISTORY_PARAMETER_NAMES)
    if unknown:
        raise ProviderRequestError(
            "unsupported AKShare history parameter(s): " + ", ".join(unknown),
            request=request,
            retryable=False,
        )
    period = str(parameters.get("period", "daily")).lower()
    adjust = str(parameters.get("adjust", ""))
    if period not in {"daily", "weekly", "monthly"}:
        raise ProviderRequestError(
            "history period must be daily, weekly or monthly",
            request=request,
            retryable=False,
        )
    if adjust not in {"", "qfq", "hfq"}:
        raise ProviderRequestError(
            "history adjust must be '', 'qfq' or 'hfq'",
            request=request,
            retryable=False,
        )
    if listing.market is ListingMarket.H and period != "daily":
        raise ProviderRequestError(
            "the AKShare H-share history endpoint supports daily observations only",
            request=request,
            retryable=False,
        )

    start_text, start_date = _date_parameter(parameters, "start_date", "start_year")
    end_text, end_date = _date_parameter(parameters, "end_date", "end_year")
    if start_date is not None and end_date is not None and start_date > end_date:
        raise ProviderRequestError(
            "history start_date must not be after end_date",
            request=request,
            retryable=False,
        )

    if endpoint_name == "stock_hk_daily":
        return {"symbol": listing.code, "adjust": adjust}
    if endpoint_name == "stock_zh_ah_daily":
        kwargs: dict[str, object] = {"symbol": listing.code, "adjust": adjust}
        if start_date is not None:
            kwargs["start_year"] = str(start_date.year)
        if end_date is not None:
            kwargs["end_year"] = str(end_date.year)
        return kwargs

    if endpoint_name == "stock_zh_a_daily":
        kwargs = {
            "symbol": listing.canonical_id[:2].lower() + listing.code,
            "adjust": adjust,
        }
        if start_text is not None:
            kwargs["start_date"] = start_text
        if end_text is not None:
            kwargs["end_date"] = end_text
        return kwargs

    kwargs = {"symbol": listing.code, "period": period, "adjust": adjust}
    if start_text is not None:
        kwargs["start_date"] = start_text
    if end_text is not None:
        kwargs["end_date"] = end_text
    return kwargs


